import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"ChatGPT Work","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/chatgpt-work.md","filePath":"products/ai-coding/codex/chatgpt-work.md","lastUpdated":1787048027000}'),s={name:"products/ai-coding/codex/chatgpt-work.md"};function n(i,t,d,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="chatgpt-work" tabindex="-1">ChatGPT Work <a class="header-anchor" href="#chatgpt-work" aria-label="Permalink to &quot;ChatGPT Work&quot;">​</a></h1><blockquote><p>ChatGPT Work is the agent mode that takes a task to a <strong>reviewable result</strong>: a brief, a deck, a spreadsheet, a hosted site, a recurring update. It is not Chat, and it is not Codex.</p><p>Official wording: “ChatGPT Work is a way to delegate real work to ChatGPT.” Start at <a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with ChatGPT Work</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Account</td><td>Any ChatGPT plan; surfaces and limits are on the <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">pricing page</a></td></tr><tr><td>Web</td><td>The Work switcher at <a href="https://chatgpt.com/" target="_blank" rel="noreferrer">chatgpt.com</a></td></tr><tr><td>Desktop</td><td>The <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a> (macOS / Windows; Linux is preview)</td></tr><tr><td>Local files / apps</td><td><strong>Work locally</strong> in the desktop app</td></tr><tr><td>Keep running after you close the laptop</td><td><strong>Cloud</strong>, or Work on the web</td></tr></tbody></table><p><strong>Learning objectives</strong>: tell Chat / Work / Codex apart; delegate one task with a clear deliverable; know local vs cloud; use plugins and scheduled tasks.</p><p><strong>Non-goals</strong>: CLI sandbox setup (<a href="./codex-cli.html">Codex CLI</a>); prices and quotas (<a href="./chatgpt-plus.html">Plans and access</a>).</p><h2 id="what-work-is-—-and-is-not" tabindex="-1">What Work is — and is not <a class="header-anchor" href="#what-work-is-—-and-is-not" aria-label="Permalink to &quot;What Work is — and is not&quot;">​</a></h2><p>Official docs split the same desktop app into three ways of working:</p><table tabindex="0"><thead><tr><th>Choose</th><th>When you want</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>A question or a short draft</td><td>Compare options, rewrite a message, clarify a brief</td></tr><tr><td><strong>ChatGPT Work</strong></td><td>An outcome you can review</td><td>An eight-slide deck, a comparison sheet, a weekly agenda</td></tr><tr><td><strong>Codex</strong></td><td>Developer views and repo-level edits</td><td>Debug, run tests, review a PR, implement a feature</td></tr></tbody></table><p>Work plans the steps, pulls in files and plugins, and stops at something you can open and check. You can follow progress, change direction, and approve consequential actions.</p><p>It is <strong>not</strong>:</p><ul><li>A replacement for Codex’s coding UI (no pull-request pane; Git / shell detail is hidden by default)</li><li>A replacement for Chat (short questions belong in Chat)</li><li>A third app you install separately (since 2026-07-09, Work and Codex live in the <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a>)</li></ul><blockquote><p>Official note: if you already used Codex for non-coding work, you can stay there or switch to Work. The capabilities overlap; the interface is built for everyday knowledge work. Work and Codex <strong>share usage limits</strong>.</p></blockquote><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th><th>Official page</th></tr></thead><tbody><tr><td>Research and analysis</td><td>Search, browse, compare sources, read files, summarize</td><td><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a></td></tr><tr><td>Files and tools</td><td>Uploads, Projects, Library, Memories, plugins</td><td><a href="https://learn.chatgpt.com/docs/projects" target="_blank" rel="noreferrer">Projects</a> · <a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td>Finished files</td><td>Documents, decks, spreadsheets, PDFs — preview, then download</td><td><a href="https://learn.chatgpt.com/docs/artifacts-viewer" target="_blank" rel="noreferrer">Work with files</a></td></tr><tr><td>Visual and hosted work</td><td>Images, visualizations, <strong>Sites</strong> for websites and apps</td><td><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a></td></tr><tr><td>Browser and desktop</td><td>Built-in browser, Chrome extension, Computer Use, Appshots</td><td><a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></td></tr><tr><td>Long tasks</td><td>Subagents, long-running work, mid-flight course changes</td><td><a href="https://learn.chatgpt.com/docs/long-running-work" target="_blank" rel="noreferrer">Long-running work</a></td></tr><tr><td>Repeatable work</td><td>Scheduled tasks + skills</td><td><a href="https://learn.chatgpt.com/docs/automations" target="_blank" rel="noreferrer">Scheduled tasks</a></td></tr></tbody></table><p>Features depend on plan, platform, region, rollout, and workspace settings. Administrators can disable Work, plugins, browser use, and network access.</p><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><h3 id="_1-switch-to-work" tabindex="-1">1. Switch to Work <a class="header-anchor" href="#_1-switch-to-work" aria-label="Permalink to &quot;1. Switch to Work&quot;">​</a></h3><p>In the web or desktop app, open the switcher and choose <strong>Work</strong>. A good first task has a clear outcome, a few source files, and a result you can review.</p><h3 id="_2-choose-local-or-cloud" tabindex="-1">2. Choose local or cloud <a class="header-anchor" href="#_2-choose-local-or-cloud" aria-label="Permalink to &quot;2. Choose local or cloud&quot;">​</a></h3><p>The desktop composer exposes <strong>Work locally</strong>. If <strong>Cloud</strong> is offered, pick by the job:</p><table tabindex="0"><thead><tr><th></th><th><strong>Cloud</strong></th><th><strong>Work locally</strong></th></tr></thead><tbody><tr><td>Runs on</td><td>An isolated OpenAI-hosted environment</td><td>Your computer</td></tr><tr><td>After you quit / sleep</td><td>Continues; resume from web or mobile</td><td>Stops</td></tr><tr><td>Local files / apps</td><td>No direct access; upload, Project, or an authorized plugin</td><td>Yes</td></tr><tr><td>Work on the web</td><td>Web Work <strong>is</strong> cloud</td><td>Desktop only</td></tr><tr><td>Use when</td><td>Long jobs, watching websites on a schedule, continuing on another device</td><td>Sorting a local folder, driving a desktop app</td></tr></tbody></table><p>Cloud scheduled tasks do not need your computer awake. Local scheduled tasks do: the machine must stay on and the desktop app must stay running.</p><h3 id="_3-specify-the-result-not-the-vibe" tabindex="-1">3. Specify the result, not the vibe <a class="header-anchor" href="#_3-specify-the-result-not-the-vibe" aria-label="Permalink to &quot;3. Specify the result, not the vibe&quot;">​</a></h3><p>Weak:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Make me a presentation about our customer research.</span></span></code></pre></div><p>The official shape: outcome, sources, constraints, what “good” looks like, and when to stop for review.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review the attached interview notes and survey results. Create an eight-slide presentation for the product leadership meeting. Focus on the three most common customer problems, include supporting evidence, separate findings from recommendations, and flag any claims that are not well supported. Use @Google Drive for the source docs. Return a draft for my review before treating it as final.</span></span></code></pre></div><h2 id="three-official-starter-tasks" tabindex="-1">Three official starter tasks <a class="header-anchor" href="#three-official-starter-tasks" aria-label="Permalink to &quot;Three official starter tasks&quot;">​</a></h2><h3 id="a-presentation" tabindex="-1">A presentation <a class="header-anchor" href="#a-presentation" aria-label="Permalink to &quot;A presentation&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review the attached source materials and create an eight-slide presentation for [audience]. Focus on the main themes, include supporting evidence, and flag anything that needs human review. Return a draft for my review.</span></span></code></pre></div><h3 id="a-comparison-spreadsheet" tabindex="-1">A comparison spreadsheet <a class="header-anchor" href="#a-comparison-spreadsheet" aria-label="Permalink to &quot;A comparison spreadsheet&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a spreadsheet comparing the options for [decision]. Use the attached notes and source materials. Include the most important criteria, score each option, flag risks or missing information, and add a summary tab with a recommendation and next steps.</span></span></code></pre></div><h3 id="a-recurring-update" tabindex="-1">A recurring update <a class="header-anchor" href="#a-recurring-update" aria-label="Permalink to &quot;A recurring update&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every Monday morning, review new updates from @Slack and @Google Drive for [project]. Refresh the meeting agenda with decisions, blockers, owners, and open questions. Send me a draft before sharing it.</span></span></code></pre></div><p>Manage runs from <strong>Scheduled</strong> in the sidebar. Details: <a href="https://learn.chatgpt.com/docs/automations?surface=app" target="_blank" rel="noreferrer">Scheduled tasks</a>.</p><h2 id="plugins-the-connector-layer" tabindex="-1">Plugins (the connector layer) <a class="header-anchor" href="#plugins-the-connector-layer" aria-label="Permalink to &quot;Plugins (the connector layer)&quot;">​</a></h2><p>Plugins are the consumer-facing counterpart to Claude Connectors: Slack, Google Drive, SharePoint, mail, calendars, CRMs, project trackers.</p><ol><li>Open <strong>Plugins</strong> in the left sidebar and install what you need.</li><li>Mention a tool with <code>@plugin-name</code> in the prompt.</li><li>Availability depends on plan, workspace, and the plugin itself.</li></ol><p>Enterprise / Edu workspaces keep plugins off by default; Business keeps them on. Making a plugin available is not the same as granting your account access — you still enable it and sign in.</p><p>Repo wiring, CI, and custom MCP stay on <a href="./integration.html">Project Integration</a>. Do not treat those as Work plugins.</p><h2 id="sites-when-you-need-a-hosted-page" tabindex="-1">Sites, when you need a hosted page <a class="header-anchor" href="#sites-when-you-need-a-hosted-page" aria-label="Permalink to &quot;Sites, when you need a hosted page&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a> is a public beta: ChatGPT creates, hosts, refines, and shares websites, internal tools, or small apps without a separate deploy stack. Web entry: <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a>. Full tutorial: <a href="./sites.html">Sites</a>.</p><p>It is <strong>not</strong> Claude Design. There is no official “import a design system from the repo, then hand off a bundle” product on the OpenAI side. Sites is a hosting workflow.</p><p>Documented constraints:</p><ul><li>Every deployment URL is production. To review first, ask it to <strong>save a version without deploying</strong>.</li><li>The CLI and IDE extension have <strong>no</strong> Sites management UI; create and publish from web or the desktop app.</li><li>Enterprise workspaces keep public publishing off by default.</li><li>No data residency at launch; do not process PHI or payment-card data.</li></ul><p>For frontend work: implement and test in the repo with Codex, then publish via Sites — or use Work for a throwaway internal dashboard. Do not treat Sites as your production frontend stack.</p><h2 id="work-vs-codex-on-desktop" tabindex="-1">Work vs Codex on desktop <a class="header-anchor" href="#work-vs-codex-on-desktop" aria-label="Permalink to &quot;Work vs Codex on desktop&quot;">​</a></h2><p>Official comparison (<a href="https://learn.chatgpt.com/docs/use-chatgpt#compare-chatgpt-work-and-codex-on-desktop" target="_blank" rel="noreferrer">Use ChatGPT</a>):</p><table tabindex="0"><thead><tr><th>Difference</th><th>ChatGPT (including Work)</th><th>Codex in the desktop app</th></tr></thead><tbody><tr><td>Where to start</td><td>Select <strong>ChatGPT</strong>, then <strong>Work</strong></td><td>Select <strong>Codex</strong> in the product selector</td></tr><tr><td>Chats you see</td><td>Chat from web/mobile plus Work</td><td>Codex chats and development projects</td></tr><tr><td>Technical detail</td><td>Hides Git / shell by default</td><td>Shows diffs and review views</td></tr><tr><td>Voice</td><td>Prefers non-technical, finished outputs</td><td>Can include implementation detail</td></tr><tr><td>Pull requests pane</td><td>Not available in Work</td><td>Available when enabled</td></tr></tbody></table><p>Changing code, inspecting a diff, or driving a PR → Codex. A file someone else can open → Work.</p><h2 id="safety-boundaries-worth-internalizing" tabindex="-1">Safety boundaries worth internalizing <a class="header-anchor" href="#safety-boundaries-worth-internalizing" aria-label="Permalink to &quot;Safety boundaries worth internalizing&quot;">​</a></h2><ul><li>The <strong>cloud browser</strong> is not your Chrome: no local tabs, extensions, history, or passwords, and it cannot sign in or pay. Unsupported steps stop the task.</li><li><strong>Local Work</strong> can reach files and apps you authorize. Do not point it at a secrets directory.</li><li>Review approval prompts before spend, account changes, or outbound sends.</li><li>Admin policy wins. Turning on public internet access does not override a workspace restriction.</li></ul><p>Enterprise isolation, retention, and compliance: <a href="https://learn.chatgpt.com/docs/enterprise/chatgpt-work-overview" target="_blank" rel="noreferrer">ChatGPT Work Overview</a>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Opening Work for a one-line question</td><td>Multi-step agent work burns more quota</td><td>Use Chat</td></tr><tr><td>Editing a repo in Work and looking for the PR pane</td><td>Work has no PR sidebar</td><td>Switch to Codex</td></tr><tr><td>Expecting a local schedule to run on a sleeping laptop</td><td>It will not</td><td>Use Cloud when the job is not local</td></tr><tr><td>Treating a Sites URL as staging</td><td>Deploy URLs are production</td><td>Save a version; deploy after review</td></tr><tr><td>Prompting “make a deck”</td><td>Polished slides with thin evidence</td><td>Name the audience, sources, and review gate</td></tr><tr><td>Assuming an installed plugin is authorized</td><td>Enterprise defaults off; OAuth is per user</td><td>Enable it and sign in</td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>A frontend weekly: Work pulls decisions from <code>@Slack</code> and <code>@Google Drive</code> into an agenda draft; the actual code change goes to <a href="./codex-cli.html">Codex CLI</a> or desktop Codex. Keep the design conversation in Chat. Do not mix it into the same Work thread as the implementation.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Still choosing a surface → the decision tree on the <a href="./">Learning Map</a>.</li><li>Writing code → <a href="./codex-cli.html">Codex CLI</a> or the <a href="./codex-ai.html">product line</a>.</li><li>Plans and the Chat surface → <a href="./chatgpt-plus.html">ChatGPT Plans and Access</a>.</li><li>Wiring a real repo → <a href="./integration.html">Project Integration</a>.</li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with ChatGPT Work</a></li><li><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a> (Chat / Work / Codex)</li><li><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a></li><li><a href="https://learn.chatgpt.com/docs/automations" target="_blank" rel="noreferrer">Scheduled tasks</a></li><li><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a></li><li><a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></li><li><a href="https://learn.chatgpt.com/docs/enterprise/chatgpt-work-overview" target="_blank" rel="noreferrer">ChatGPT Work Overview</a></li><li><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a> (2026-07-09 Work + desktop merge)</li></ul>',62)])])}const m=e(s,[["render",n]]);export{k as __pageData,m as default};
